    "summary": "Require every declared integer term cell to be present and resolvable and every checked linear term to contribute to one exact integer target.",
    "availability": "implemented",
    "execution_kind": "constraint",
    "default_strength": "hard",
    "authorities": [
      {
        "kind": "industry_specification",
        "title": "XBRL Calculation Requirements 1.1 - Summation Consistency",
        "url": "https://www.xbrl.org/REQ/calculation-requirements-1.1/REQ-2022-05-25/calculation-requirements-1.1-2022-05-25.html"
      }
    ],
    "requires": [
      "aggregate_balances[subject].terms",
      "aggregate_balances[subject].target",
      "relations[term.relation].rows[term.row].cells[term.field]"
    ],
    "valid_example": {
      "facts": {
        "family": "data_integrity",
        "mode": "verify",
        "rules": [
          {
            "rule_id": "data_integrity.aggregate_balance",
            "subjects": [
              "ledger_balance"
            ],
            "parameters": {}
          }
        ],
        "facts": {
          "relations": {
            "ledger": {
              "fields": {
                "amount": {
                  "kind": "integer",
                  "minimum": -2000,
                  "maximum": 2000
                }
              },
              "rows": {
                "left": {
                  "active": true,
                  "cells": {
                    "amount": {
                      "present": true,
                      "value": 100
                    }
                  }
                },
                "delta": {
                  "active": false,
                  "cells": {
                    "amount": {
                      "present": true,
                      "value": -30
                    }
                  }
                },
                "right": {
                  "active": true,
                  "cells": {
                    "amount": {
                      "present": true,
                      "value": 70
                    }
                  }
                }
              }
            }
          },
          "unique_constraints": {},
          "foreign_keys": {},
          "cardinality_constraints": {},
          "value_ranges": {},
          "conditional_requirements": {},
          "aggregate_balances": {
            "ledger_balance": {
              "terms": [
                {
                  "relation": "ledger",
                  "row": "left",
                  "field": "amount",
                  "coefficient": 1
                },
                {
                  "relation": "ledger",
                  "row": "delta",
                  "field": "amount",
                  "coefficient": 1
                },
                {
                  "relation": "ledger",
                  "row": "right",
                  "field": "amount",
                  "coefficient": -1
                }
              ],
              "target": 0
            }
          },
          "consistency_relations": {},
          "temporal_constraints": {}
        },
        "unknowns": []
      },
      "expectation": "exact integer balance 100 plus negative 30 equals 70"
    }
