    "execution_kind": "constraint",
    "default_strength": "hard",
    "authorities": [
      {
        "kind": "official_database_documentation",
        "title": "PostgreSQL CREATE TABLE - Referential Actions and MATCH Types",
        "url": "https://www.postgresql.org/docs/current/sql-createtable.html"
      }
    ],
    "requires": [
      "relations[definition.child_relation].rows",
      "relations[definition.parent_relation].rows",
      "foreign_keys[subject].child_fields",
      "foreign_keys[subject].parent_fields"
    ],
    "valid_example": {
      "facts": {
        "family": "data_integrity",
        "mode": "verify",
        "rules": [
          {
            "rule_id": "data_integrity.foreign_key",
            "subjects": [
              "child_parent"
            ],
            "parameters": {}
          }
        ],
        "facts": {
          "relations": {
            "parents": {
              "fields": {
                "key": {
                  "kind": "integer",
                  "minimum": 0,
                  "maximum": 1000
                }
              },
              "rows": {
                "parent": {
                  "active": true,
                  "cells": {
                    "key": {
                      "present": true,
                      "value": 7
                    }
                  }
                }
              }
            },
            "children": {
              "fields": {
                "parent_key": {
                  "kind": "integer",
                  "minimum": 0,
                  "maximum": 1000
                }
              },
              "rows": {
                "matched": {
                  "active": true,
                  "cells": {
                    "parent_key": {
                      "present": true,
                      "value": 7
                    }
                  }
                },
                "absent": {
                  "active": true,
                  "cells": {
                    "parent_key": {
                      "present": false,
                      "value": null
                    }
                  }
                }
              }
            }
          },
          "unique_constraints": {},
          "foreign_keys": {
            "child_parent": {
              "child_relation": "children",
              "child_fields": [
                "parent_key"
              ],
              "parent_relation": "parents",
              "parent_fields": [
                "key"
              ]
            }
          },
          "cardinality_constraints": {},
          "value_ranges": {},
          "conditional_requirements": {},
          "aggregate_balances": {},
          "consistency_relations": {},
          "temporal_constraints": {}
        },
        "unknowns": []
      },
      "expectation": "complete child key matches and absent child key is ignored under MATCH SIMPLE"
    }
  }
